import type { Position } from "./preflop";
import type { PreflopScenario } from "./game-state";
import { normalizeStartingHand, type StrategyMix } from "./strategy-data";

/**
 * Preflop packs are generated by tools/rangelab-preflop: one file per table size and stack depth, each listing every
 * reachable decision spot with per-hand fold/passive frequencies in permille (aggressive is the remainder).
 */
export type TableSize=6|8;
export const packStackBuckets=[20,40,60,100,150] as const;

export interface PackSpot {
  position:Position;scenario:PreflopScenario;
  openerPosition?:Position;aggressorPosition?:Position;callerPositions:Position[];limperPositions:Position[];
  actionSize?:number;reach:number;
  /** Indexed like the pack's `hands`. */
  mix:[number,number][];
}
export interface PreflopPack { id:string;license:string;generatedAt:string;tableSize:TableSize;stack:number;provenance:Record<string,unknown>;hands:string[];spots:PackSpot[]; }

const CONTRACT="rangelab.preflop_pack.v1";
const PERMILLE=1000;
/** The largest 6-max pack is 0.56 MB; 8-max packs have more positions, so this leaves room for them. */
const MAX_PACK_CHARS=4_000_000;
const MAX_SPOTS=50_000;
/** Packs stop at facing a 4-bet; later raises are not in them. */
const MAX_PACK_RAISES=3;
/** A spot or stack this many times off the request is a different situation, so the pack is not used. */
const MAX_SIZE_RATIO=2.5;
/** Failed loads are not retried for this long, so editing the stack cannot hammer a broken file. */
const FAILED_LOAD_RETRY_MS=60_000;
const TABLE_POSITIONS:Record<TableSize,Position[]>={6:["UTG","HJ","CO","BTN","SB","BB"],8:["UTG","UTG+1","MP","HJ","CO","BTN","SB","BB"]};
const SCENARIOS=new Set<PreflopScenario>(["unopened","limped","single-open","open-with-callers","facing-3bet","facing-4bet"]);

const isRecord=(value:unknown):value is Record<string,unknown>=>Boolean(value)&&typeof value==="object"&&!Array.isArray(value);

function parseSpot(raw:unknown,index:number,positions:Set<string>):PackSpot{
  const fail=(field:string)=>new Error(`Pack spot ${index+1}: invalid ${field}.`);
  if(!isRecord(raw))throw fail("spot");
  const position=(value:unknown,field:string)=>{if(typeof value!=="string"||!positions.has(value))throw fail(field);return value as Position;};
  const optionalPosition=(value:unknown,field:string)=>value===undefined?undefined:position(value,field);
  const positionList=(value:unknown,field:string)=>{if(value!==undefined&&(!Array.isArray(value)||value.length>positions.size))throw fail(field);return ((value as unknown[]|undefined)??[]).map(item=>position(item,field));};
  if(typeof raw.scenario!=="string"||!SCENARIOS.has(raw.scenario as PreflopScenario))throw fail("scenario");
  if(raw.actionSize!==undefined&&typeof raw.actionSize!=="string"&&typeof raw.actionSize!=="number")throw fail("actionSize");
  const actionSize=raw.actionSize===undefined?undefined:Number(raw.actionSize);
  if(actionSize!==undefined&&!(Number.isFinite(actionSize)&&actionSize>0))throw fail("actionSize");
  if(typeof raw.reach!=="number"||!Number.isFinite(raw.reach)||raw.reach<0||raw.reach>1)throw fail("reach");
  if(!Array.isArray(raw.mix)||raw.mix.length!==169)throw fail("mix");
  const mix=raw.mix.map(entry=>{
    if(!Array.isArray(entry)||entry.length!==2)throw fail("mix");
    const [fold,passive]=entry as unknown[];
    if(!Number.isInteger(fold)||!Number.isInteger(passive)||(fold as number)<0||(passive as number)<0||(fold as number)+(passive as number)>PERMILLE)throw fail("mix");
    return [fold,passive] as [number,number];
  });
  return {
    position:position(raw.position,"position"),scenario:raw.scenario as PreflopScenario,
    openerPosition:optionalPosition(raw.openerPosition,"openerPosition"),aggressorPosition:optionalPosition(raw.aggressorPosition,"aggressorPosition"),
    callerPositions:positionList(raw.callerPositions,"callerPositions"),limperPositions:positionList(raw.limperPositions,"limperPositions"),
    actionSize,reach:raw.reach,mix,
  };
}

export function parsePreflopPack(text:string):PreflopPack{
  if(text.length>MAX_PACK_CHARS)throw new Error("Preflop pack is too large.");
  let value:unknown;
  try{value=JSON.parse(text);}catch{throw new Error("Preflop pack is not valid JSON.");}
  if(!isRecord(value))throw new Error("Preflop pack must be a JSON object.");
  if(value.contract!==CONTRACT)throw new Error(`Preflop pack contract must be ${CONTRACT}.`);
  if(value.tableSize!==6&&value.tableSize!==8)throw new Error("Preflop pack tableSize must be 6 or 8.");
  if(!Number.isInteger(value.stack)||(value.stack as number)<10||(value.stack as number)>300)throw new Error("Preflop pack stack is invalid.");
  if(typeof value.id!=="string"||!/^[a-z0-9][a-z0-9._-]+$/i.test(value.id)||typeof value.license!=="string"||typeof value.generatedAt!=="string")throw new Error("Preflop pack needs id, license, and generatedAt.");
  const hands=value.hands;
  if(!Array.isArray(hands)||hands.length!==169||new Set(hands).size!==169||hands.some(hand=>typeof hand!=="string"||normalizeStartingHand(hand)!==hand))throw new Error("Preflop pack must list all 169 starting hands.");
  if(!Array.isArray(value.spots)||value.spots.length>MAX_SPOTS)throw new Error(`Preflop pack spots must be an array of at most ${MAX_SPOTS}.`);
  const positions=new Set<string>(TABLE_POSITIONS[value.tableSize]);
  const spots=value.spots.map((spot,index)=>parseSpot(spot,index,positions));
  const keys=new Set<string>();
  for(const spot of spots){
    const key=`${spotKey(spot)}|${spot.actionSize??""}`;
    if(keys.has(key))throw new Error(`Preflop pack has a duplicate spot: ${key}.`);
    keys.add(key);
  }
  return {
    id:value.id,license:value.license,generatedAt:value.generatedAt,tableSize:value.tableSize,stack:value.stack as number,
    provenance:isRecord(value.provenance)?value.provenance:{},hands:hands as string[],spots,
  };
}

const sortedPositions=(positions:Position[]=[])=>[...positions].sort().join("+");
/** Everything that identifies a spot except the bet size, which is matched by distance. */
function spotKey(spot:{position:Position;scenario:PreflopScenario;openerPosition?:Position;aggressorPosition?:Position;callerPositions?:Position[];limperPositions?:Position[]}){
  return [spot.position,spot.scenario,spot.openerPosition??"",spot.aggressorPosition??"",sortedPositions(spot.callerPositions),sortedPositions(spot.limperPositions)].join("|");
}

interface InstalledPack { pack:PreflopPack;handIndex:Map<string,number>;spotsByKey:Map<string,PackSpot[]>; }
const installed=new Map<string,InstalledPack>();
const packKey=(tableSize:TableSize,stack:number)=>`${tableSize}:${stack}`;

export function installPreflopPack(pack:PreflopPack){
  const spotsByKey=new Map<string,PackSpot[]>();
  for(const spot of pack.spots){
    const key=spotKey(spot);
    const sameSpot=spotsByKey.get(key);
    if(sameSpot)sameSpot.push(spot);else spotsByKey.set(key,[spot]);
  }
  installed.set(packKey(pack.tableSize,pack.stack),{pack,handIndex:new Map(pack.hands.map((hand,index)=>[hand,index])),spotsByKey});
}

export function clearPreflopPacks(){installed.clear();loading.clear();failures.clear();}

export interface PackLookup {
  tableSize:TableSize;stack:number;hand:string;position:Position;scenario:PreflopScenario;
  openerPosition?:Position;aggressorPosition?:Position;callerPositions?:Position[];limperPositions?:Position[];actionSize?:number;
  /** Opens and re-raises so far; packs have nothing beyond facing a 4-bet. */
  raiseCount?:number;
}

const ratio=(left:number,right:number)=>Math.max(left,right)/Math.min(left,right);
/** Nearest stack first; equal distances go to the smaller stack, the order the loader tries buckets in. */
const stackDistance=(stack:number,target:number)=>[Math.abs(stack-target),stack] as const;
const closer=(left:readonly [number,number],right:readonly [number,number])=>left[0]<right[0]||(left[0]===right[0]&&left[1]<right[1]);

/** The pack strategy for an exact spot match (nearest bet size breaks ties), or null to fall back to other data. */
export function lookupPackStrategy(input:PackLookup):StrategyMix|null{
  if((input.raiseCount??0)>MAX_PACK_RAISES||!(input.stack>0))return null;
  const candidates=[...installed.values()].filter(entry=>entry.pack.tableSize===input.tableSize);
  if(!candidates.length)return null;
  const nearest=candidates.reduce((best,entry)=>closer(stackDistance(entry.pack.stack,input.stack),stackDistance(best.pack.stack,input.stack))?entry:best);
  if(ratio(nearest.pack.stack,input.stack)>MAX_SIZE_RATIO)return null;
  const hand=normalizeStartingHand(input.hand);
  const index=hand===null?undefined:nearest.handIndex.get(hand);
  if(index===undefined)return null;
  const matches=nearest.spotsByKey.get(spotKey(input));
  if(!matches?.length)return null;
  const spot=matches.reduce((best,candidate)=>Math.abs((candidate.actionSize??0)-(input.actionSize??0))<Math.abs((best.actionSize??0)-(input.actionSize??0))?candidate:best);
  if(spot.actionSize!==undefined&&input.actionSize!==undefined&&ratio(spot.actionSize,input.actionSize)>MAX_SIZE_RATIO)return null;
  const [fold,passive]=spot.mix[index];
  return {fold:fold/10,passive:passive/10,aggressive:(PERMILLE-fold-passive)/10,source:`pack:${nearest.pack.id}`};
}

const loading=new Map<string,Promise<PreflopPack|null>>();
const failures=new Map<string,number>();

/** The buckets to try for a stack, nearest first and the smaller stack first on ties. */
export function bucketOrder(stack:number){
  return [...packStackBuckets].sort((left,right)=>closer(stackDistance(left,stack),stackDistance(right,stack))?-1:1);
}

/** A bucket file that is present but unusable is reported and skipped so a farther bucket can still be used. */
function skipBucket(tableSize:TableSize,bucket:number,reason:string):null{
  console.warn(`Skipping preflop pack ${tableSize}max-${bucket}bb: ${reason}`);
  return null;
}

async function fetchBucket(tableSize:TableSize,bucket:number,fetchImpl:typeof fetch):Promise<PreflopPack|null>{
  const response=await fetchImpl(`/data/preflop/${tableSize}max-${bucket}bb.json`);
  if(response.status===404)return null;
  if(!response.ok)throw new Error(`Preflop pack request failed (HTTP ${response.status}).`);
  // A dev server or SPA fallback can answer a missing file with an HTML page.
  if((response.headers.get("content-type")??"").includes("text/html"))return skipBucket(tableSize,bucket,"an HTML page");
  const declared=Number(response.headers.get("content-length"));
  if(Number.isFinite(declared)&&declared>MAX_PACK_CHARS)throw new Error("Preflop pack is too large.");
  let pack:PreflopPack;
  try{pack=parsePreflopPack(await response.text());}
  catch(error){return skipBucket(tableSize,bucket,error instanceof Error?error.message:"an invalid pack");}
  if(pack.tableSize!==tableSize||pack.stack!==bucket)return skipBucket(tableSize,bucket,`${pack.tableSize}-max ${pack.stack}bb data`);
  return pack;
}

/** Fetches and installs the pack nearest to `stack` for the table size, trying farther buckets if one is missing. */
export function loadPreflopPack(tableSize:TableSize,stack:number,fetchImpl:typeof fetch=fetch):Promise<PreflopPack|null>{
  const order=bucketOrder(stack);
  const key=packKey(tableSize,order[0]);
  const cached=loading.get(key);
  if(cached)return cached;
  const failedAt=failures.get(key);
  if(failedAt!==undefined&&Date.now()-failedAt<FAILED_LOAD_RETRY_MS)return Promise.resolve(null);
  const attempt=(async()=>{
    for(const bucket of order){
      const existing=installed.get(packKey(tableSize,bucket));
      if(existing)return existing.pack;
      const pack=await fetchBucket(tableSize,bucket,fetchImpl);
      if(!pack)continue;
      installPreflopPack(pack);
      return pack;
    }
    return null;
  })();
  loading.set(key,attempt);
  // A missing or unusable pack is retried after FAILED_LOAD_RETRY_MS, so a pack generated later still loads.
  const forget=()=>{loading.delete(key);failures.set(key,Date.now());};
  attempt.then(pack=>{if(!pack)forget();},forget);
  return attempt;
}
